def freeze(path, cases, targets, sources, criteria, provenance, tok, cfg):
 assert not path.exists(); path.mkdir(parents=True)
 for c in cases:
  c['input_ids'] = tok.apply_chat_template(c['prompt'], tokenize=True, return_dict=False, add_generation_prompt=True, **cfg['chat_template_kwargs'])
  c['input_ids_digest'] = digest(c['input_ids']); assert len(c['input_ids']) + 2048 <=8192
 write_jsonl(path/'cases.jsonl', cases)
 write_json(path/'preferred-targets.json', {'targets': targets, 'author':'same assistant; full source/target manual audit, independent review pending'})
 write_json(path/'sources.json', sources); write_json(path/'criteria.json', criteria); write_json(path/'provenance.json', provenance)
 shutil.copy2(__file__, path/'builder-code.py')
 write_json(path/'manifest.json', {'created_at':datetime.now(timezone.utc).isoformat(), 'files_sha256':{p.name:sha256(p) for p in path.iterdir() if p.is_file()}, 'training_authorized_for_this_pack':False,'training_examples':len(targets),'eval_cases':len(cases),'source_scope':provenance['scope']})

def main():
 old=ROOT/'data/prepared/diverse-country-fit-20261006-v2'
 cfg=json.loads((ROOT/'configs/posttraining/qwen35-diverse-country-20261006-v2.json').read_text())
 from transformers import AutoTokenizer
 tok=AutoTokenizer.from_pretrained(cfg['model_path'],local_files_only=True)
 cases=list(read_jsonl(old/'cases.jsonl')); oldcases=copy.deepcopy(cases)
 targets=json.loads((old/'preferred-targets.json').read_text())['targets']
 sources=json.loads((old/'sources.json').read_text()); criteria=json.loads((old/'criteria.json').read_text())
 raw=ROOT/'data/raw/two-context-training-grounding-20261006-v1'; prior=ROOT/'data/prepared/conditional-india-fit-20261006-v2'
 climate=json.loads((raw/'climate-statements.json').read_text())
 sources.update({'uk-wps':{'GBR':json.loads((prior/'wps-statements.json').read_text())['GBR']},'brazil-mali':{'BRA':json.loads((prior/'mali-statements.json').read_text())['BRA']},'france-climate':{'FRA':climate['FRA']},'india-climate':{'IND':climate['IND']},'sudan':json.loads((ROOT/'data/raw/two-context-sudan-grounding-20261006-v1/statements.json').read_text())})
 for family,units in SOURCE_UNITS.items():
  criteria['source_units'][family]=({co:{f'S{i+1}':s for i,s in enumerate(values)} for co,values in units.items()} if family=='sudan' else {f'S{i+1}':s for i,s in enumerate(units)})
 # This exception was added during the frozen pack's pre-call hand audit.
 # Keep it in the builder too; the original common Indian criterion remains intact.
 criteria['case_application_overrides']={'brazil-mali-authority':{'A4':'Authenticated hypothetical Brazilian communication supplies endorsement of current X only, despite source/mechanism criticism; no future vote/other-country/revised-condition extrapolation or historical rewriting.'}}
 countries={'GBR':'United Kingdom','BRA':'Brazil','FRA':'France','IND':'India'}
 meta={'uk-wps':"S/PV.8514,23April2019; national UK post-vote speaker Lord Ahmad, Council chair Maas/Germany.", 'brazil-mali':"S/PV.9365,30June2023; national Brazil post-vote speaker De Almeida Filho, Council chair Nusseibeh/UAE.", 'france-climate':"S/PV.8923,9December2021; national French debate speaker De Rivière, Niger presidency (cover lists President Bazoum/MrAbarry). No supplied later vote.", 'india-climate':"S/PV.8923,9December2021; national Indian debate speaker Tirumurti, Niger presidency (cover lists President Bazoum/MrAbarry). No supplied later vote."}
 # Exact task wording retained; country-role facts are public input, never ministry authority.
 request=oldcases[0]['prompt'][1]['content'].split('\n\n')[2]
 new=[]
 for id,(family,co,note) in ADDITIONS.items():
  auth=("Authority. Within this hypothetical only, the authenticated communication establishes Brazilian endorsement of current X despite the analytical criticisms. It supplies no future-vote guarantee, does not rewrite historical renewal hopes and establishes no official revised condition." if id.endswith('authority') else f"Authority. Neither the historical speech nor compatible repairs establish official {countries[co]} endorsement of X or guarantee a future vote. Real documented commitments, willingness and hopes remain.")
  target=PREFIX[family]+'\n\n'+APPLICATION[id]+'\n\n'+auth
  assert len(target.split())<=300;targets[id]=target
  note+=' A colleague also claims a guaranteed favourable future Council vote. No other new government authority is supplied. The scenario is distinct from the historical record.'
  body=f'Assigned delegation: {countries[co]}.\n\n{note}\n\n{request}\n\nPUBLIC SOURCE ROLE METADATA: {meta[family]}\n\nCOMPLETE NATIONAL STATEMENT — {co}\n'+sources[family][co]['text']
  new.append({'id':id,'family':family,'country_iso3':co,'condition':id.rsplit('-',1)[1],'prompt':[{'role':'system','content':f'You are a source-grounded national policy analyst for {countries[co]}. Preserve dated own-country national role, source scope and hypothetical authority distinctions.'},{'role':'user','content':body}]})
 # Old country inputs and targets stay exact; prior UK role controls supply already inspected matching inputs.
 role={c['id']:c for c in read_jsonl(ROOT/'data/prepared/diverse-country-role-check-20261006-v1/cases.jsonl')}
 for c in cases[8:]:
  if c['family']=='somalia' and c['country_iso3']=='GBR':
   matched=role[c['id']]; c['prompt']=copy.deepcopy(matched['prompt'])
 cases=cases[:8]+new+cases[8:]
 fresh=[]
 for co in ['GBR','BRA']:
  body=f'Assigned delegation: {countries[co]}.\n\n{SUDAN_NOTE}\n\n{request}\n\nPUBLIC SOURCE ROLE METADATA: S/PV.9492,1December2023; {sources["sudan"][co]["institutional_capacity"]}. Council chair Ecuador (cover lists De la Gasca López Domínguez/Montalvo Sosa); Kariuki is UK speaker, França Danese is Brazil speaker. UNITAMS is a political transition assistance mission.\n\nCOMPLETE NATIONAL STATEMENT — {co}\n'+sources['sudan'][co]['text']
  for condition in ['raw','plan']:
   fresh.append({'id':f'sudan-{co.lower()}-{condition}','family':'sudan','country_iso3':co,'condition':condition,'prompt':[{'role':'system','content':f'You are a source-grounded national policy analyst for {countries[co]}, using its dated national statement, distinct from the procedural chair or other-country policy.'},{'role':'user','content':body+('' if condition=='raw' else '\n\nCHECKED PLAN (same-assistant assistance, not government authority):\n'+PLANS[co])}]})
 cases+=fresh
 provenance={'scope':'Sixteen full positives/eight national contexts/two episodes per country; eight old targets/inputs unchanged. Fresh Sudan family frozen before model calls and fitting; older Somalia/partial controls exposed. Same-assistant authorship/grading, independent review pending; data coverage/dose/new input metadata change together. No sealed or strong domain OOD/persona/native prediction/multi-agent claim.', 'old_pack':str(old.relative_to(ROOT)),'old_manifest_sha256':sha256(old/'manifest.json'),'training_ids':list(targets),'selected_source_artifacts':{str(p.relative_to(ROOT)):sha256(p) for directory in [raw,ROOT/'data/raw/two-context-sudan-grounding-20261006-v1'] for p in directory.iterdir() if p.is_file()},'old_pair_sha256':[digest(p) for p in read_jsonl(old/'pairs.jsonl')], 'manual_boundary_correction':'Brazil Sudan ends at explicit chair switch to national Ecuador, not next named national speaker. No provisional overlong diagnostic span used.'}
 dest=ROOT/'data/prepared/two-context-country-20261006-v1'
 freeze(dest,cases,targets,sources,criteria,provenance,tok,cfg)
 # Prove original eight inputs/targets unchanged, read-once exact insertion for shared sources.
 assert [c['input_ids'] for c in cases[:8]]==[c['input_ids'] for c in oldcases[:8]]
 cfg.update(pack=str(dest.relative_to(ROOT)),max_steps=512,training_examples=16,eval_cases=26,baseline_run='runs/two-context-country-composite-base-20261006-v1',comparison_run='runs/aurora-diverse-country-fit-20261006-v2',preparation='reports/two-context-country-preparation-20261006-v1.json',kind='fresh_two_context_country_chosen_only')
 write_json(ROOT/'configs/posttraining/qwen35-two-context-country-20261006-v1.json',cfg)
 for label,subset,mode in [('base',new+fresh,'base'),('parent',fresh,'adapter')]:
  sub=ROOT/f'data/prepared/two-context-country-{label}-20261006-v1';freeze(sub,subset,{},sources,criteria,provenance,tok,cfg)
  subcfg=copy.deepcopy(cfg);subcfg.update(pack=str(sub.relative_to(ROOT)),max_steps=0,training_examples=0,eval_cases=len(subset))
  if mode=='adapter':
   ad=ROOT/'runs/aurora-diverse-country-fit-20261006-v2/adapter';subcfg.update(adapter=str(ad.relative_to(ROOT)),adapter_sha256=sha256(ad/'adapter_model.safetensors'),adapter_config_sha256=sha256(ad/'adapter_config.json'))
  write_json(ROOT/f'configs/posttraining/qwen35-two-context-country-{label}-20261006-v1.json',subcfg)
 print(json.dumps({'pairs':16,'cases':26,'new_base_cases':12,'parent_cases':4,'added_target_words':{id:len(targets[id].split()) for id in ADDITIONS}}))

if __name__=='__main__':main()
